#!/bin/bash
# Generate code from proto files

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
PROTO_DIR="$PROJECT_ROOT/proto"

echo "Generating Rust code..."
# Rust code is generated by prost-build during cargo build

echo "Generating C++ code..."
if command -v protoc &> /dev/null; then
    mkdir -p "$PROJECT_ROOT/client/cpp/generated"
    protoc \
        --proto_path="$PROTO_DIR" \
        --cpp_out="$PROJECT_ROOT/client/cpp/generated" \
        "$PROTO_DIR/crypto_api.proto"
    echo "C++ code generated in client/cpp/generated/"
else
    echo "Warning: protoc not found, skipping C++ code generation"
fi

echo "Done!"
